content.css:
html,
body {
  margin: 0;
  padding: 0;
  overflow: hidden;
  font-family: "Segoe UI", wf_standard-font, -apple-system, BlinkMacSystemFont, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.cv-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #8C9197;
  font-size: 11px;
}
/* Theme tokens are set on the root by visual.ts from the active skin. */
.sift-calendar-root {
  --sc-bg: #F4F7F5;
  --sc-surface: #FFFFFF;
  --sc-line: #E1EAE4;
  --sc-text: #0F1A14;
  --sc-muted: #52665B;
  --sc-accent: #15803D;
  --sc-accent-text: #FFFFFF;
  --sc-ring: #047857;
  --sc-pill: #E8F0EB;
  --sc-pill-text: #0F1A14;
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  position: relative;
  background: var(--sc-bg);
  color: var(--sc-text);
}
.sift-calendar-root * {
  box-sizing: border-box;
}
/* Toolbar */
.sc-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--sc-line);
}
.sc-presets {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}
.sc-preset-pill {
  appearance: none;
  background: var(--sc-pill);
  color: var(--sc-pill-text);
  border: 1px solid transparent;
  border-radius: 12px;
  padding: 3px 9px;
  font: inherit;
  font-size: 11px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
}
.sc-preset-pill:hover {
  border-color: var(--sc-accent);
}
.sc-preset-pill.active {
  background: var(--sc-accent);
  color: var(--sc-accent-text);
  font-weight: 600;
}
.sc-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.sc-btn,
.sc-select {
  font: inherit;
  font-size: 11px;
  border-radius: 6px;
  border: 1px solid var(--sc-line);
  background: var(--sc-surface);
  color: var(--sc-text);
  cursor: pointer;
  height: 26px;
}
.sc-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 0 8px;
  font-weight: 500;
}
.sc-btn:hover:not(:disabled) {
  border-color: var(--sc-accent);
}
.sc-btn:disabled {
  opacity: 0.45;
  cursor: default;
}
.sc-btn.active {
  background: var(--sc-accent);
  color: var(--sc-accent-text);
  border-color: var(--sc-accent);
}
.sc-btn svg {
  width: 14px;
  height: 14px;
}
.sc-select {
  padding: 0 8px;
  outline: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 130px;
  justify-content: space-between;
}
.sc-select:focus-visible,
.sc-select[aria-expanded="true"] {
  border-color: var(--sc-accent);
}
/* Custom dropdown (native <select> popups mis-position inside Power BI's scaled canvas) */
.sc-dd {
  position: relative;
}
.sc-dd-chevron {
  width: 7px;
  height: 7px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: translateY(-2px) rotate(45deg);
  flex-shrink: 0;
}
.sc-dd-list {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 50;
  min-width: 100%;
  overflow-y: auto;
  padding: 4px;
  background: var(--sc-surface);
  color: var(--sc-text);
  border: 1px solid var(--sc-line);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
  outline: none;
}
.sc-dd-item {
  padding: 6px 10px;
  font-size: 11px;
  border-radius: 5px;
  white-space: nowrap;
  cursor: pointer;
}
.sc-dd-item.active {
  background: var(--sc-pill);
}
.sc-dd-item[aria-selected="true"] {
  font-weight: 600;
  color: var(--sc-accent);
}
.sc-btn:focus-visible,
.sc-preset-pill:focus-visible,
.sc-crumb:focus-visible {
  outline: 2px solid var(--sc-ring);
  outline-offset: 1px;
}
/* Drill trail */
.sc-drill-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 12px;
  font-size: 11px;
  border-bottom: 1px dashed var(--sc-line);
}
.sc-crumbs {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}
.sc-crumb {
  appearance: none;
  border: 0;
  background: none;
  padding: 0;
  font: inherit;
  color: var(--sc-muted);
  cursor: pointer;
}
.sc-crumb:hover {
  color: var(--sc-text);
  text-decoration: underline;
}
.sc-crumb.current {
  color: var(--sc-text);
  font-weight: 600;
  cursor: default;
  text-decoration: none;
}
.sc-crumb-sep,
.sc-hint {
  color: var(--sc-muted);
}
.sc-hint {
  margin-left: 8px;
  font-style: italic;
  font-size: 11px;
}
/* Calendar body */
.sc-body {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
  background: var(--sc-surface);
  outline: none;
}
.sc-body:focus-visible {
  box-shadow: inset 0 0 0 2px var(--sc-ring);
}
.sc-empty {
  margin: auto;
  color: var(--sc-muted);
  font-size: 13px;
  text-align: center;
}
.sc-svg-canvas {
  display: block;
  flex-shrink: 0;
  overflow: visible;
}
.sc-cell {
  cursor: pointer;
  stroke: transparent;
  stroke-width: 1.5px;
  transition: opacity 0.12s ease;
}
.sc-cell:hover {
  stroke: var(--sc-text);
}
.sc-cell.dim,
.sc-cell.sc-unhl {
  opacity: 0.28;
}
.sc-cell.selected {
  stroke: var(--sc-ring);
  stroke-width: 2px;
}
.sc-cell.focus {
  stroke: var(--sc-text);
  stroke-width: 2px;
  stroke-dasharray: 3 2;
}
.sc-cell.in-drag-range {
  opacity: 1;
  stroke: var(--sc-ring);
  stroke-width: 2px;
  stroke-dasharray: 2 1;
}
.sc-label {
  font-size: 10px;
  font-weight: 500;
  fill: var(--sc-muted);
  dominant-baseline: central;
  pointer-events: none;
}
.sc-year-label {
  font-size: 12px;
  font-weight: 700;
  fill: var(--sc-text);
  dominant-baseline: central;
  pointer-events: none;
}
/* Month blocks */
.sc-month-grid {
  display: grid;
  gap: 12px;
}
.sc-month-card {
  border: 1px solid var(--sc-line);
  border-radius: 8px;
  padding: 8px;
}
.sc-month-title {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 6px;
}
.sc-month-total {
  font-weight: 500;
  color: var(--sc-muted);
}
/* Race playback */
.sc-race-controls {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 12px;
  border-top: 1px solid var(--sc-line);
}
.sc-race-slider {
  flex: 1;
  accent-color: var(--sc-accent);
  cursor: pointer;
}
.sc-race-label {
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  min-width: 72px;
  text-align: right;
}
/* Plain-words caption */
.sc-caption {
  padding: 8px 12px;
  line-height: 1.4;
  border-top: 1px solid var(--sc-line);
  display: flex;
  align-items: center;
  gap: 6px;
}
.sc-caption svg {
  flex-shrink: 0;
  width: 15px;
  height: 15px;
  color: var(--sc-accent);
}
/* Tooltip (lives on document.body, so it does not inherit theme vars) */
.sc-tooltip {
  position: fixed;
  pointer-events: none;
  z-index: 1000;
  background: #0F172A;
  color: #FFFFFF;
  border-radius: 8px;
  padding: 10px 12px;
  font-family: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, Helvetica, Arial, sans-serif;
  font-size: 11px;
  line-height: 1.4;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.35);
  min-width: 150px;
  max-width: 260px;
  display: none;
  border: 1px solid rgba(255, 255, 255, 0.12);
}
.sc-tooltip .sc-tt-date {
  font-weight: 700;
  font-size: 12px;
  margin-bottom: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.15);
  padding-bottom: 3px;
}
.sc-tooltip .sc-tt-val {
  font-size: 15px;
  font-weight: 800;
  color: #34D399;
  margin-bottom: 4px;
}
.sc-tooltip .sc-tt-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 2px;
  opacity: 0.92;
}
.sc-tooltip .sc-tt-badge {
  display: inline-block;
  margin: 6px 4px 0 0;
  padding: 2px 6px;
  border-radius: 4px;
  background: #F59E0B;
  color: #000000;
  font-weight: 600;
  font-size: 10px;
}
.sc-tooltip .sc-tt-alert {
  background: #EF4444;
  color: #FFFFFF;
}
/* Texture overlays dim together with the cell they sit on */
.sc-defs {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
}
.sc-cell.dim + .sc-tx,
.sc-cell.sc-unhl + .sc-tx {
  opacity: 0.28;
}
/* Colour legend */
.sc-legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 14px;
  padding: 5px 12px;
  font-size: 11px;
  color: var(--sc-muted);
  border-top: 1px solid var(--sc-line);
}
.sc-lg-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}
.sc-lg-sw {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  border: 1px solid var(--sc-line);
}
.sc-lg-bar {
  width: 120px;
  height: 10px;
  border-radius: 5px;
  border: 1px solid var(--sc-line);
}
.sc-lg-end {
  font-variant-numeric: tabular-nums;
}
.sc-tooltip .sc-neg {
  color: #F87171;
}
/* Dashboard tiles (host disallows interactions): read-only */
.sc-static .sc-header,
.sc-static .sc-drill-bar {
  display: none !important;
}
.sc-static .sc-cell {
  cursor: default;
}
/* Windows high-contrast: keep the day colours, outline them with the system colours */
.sc-hc .sc-cell {
  stroke: var(--sc-text);
  stroke-width: 1px;
}
.sc-hc .sc-cell.selected {
  stroke: var(--sc-ring);
  stroke-width: 3px;
}
.sc-hc .sc-btn,
.sc-hc .sc-select,
.sc-hc .sc-preset-pill {
  border: 1px solid var(--sc-text);
}
